function MyButton({ onClick, label = "Click Me" }) {
  return (
    <button
      onClick={onClick}
      style={{
        padding: "12px 24px",
        fontSize: "16px",
        color: "white",
        backgroundColor: "#4CAF50",
        border: "none",
        borderRadius: "8px",
