  );
}
```

### Python (Tkinter) Button
```python
import tkinter as tk

root = tk.Tk()
root.geometry("300x150")

button = tk.Button(
    root,
    text="Click Me",
    command=lambda: print("Button clicked!"),
    padx=20,
    pady=10,
    font=("Arial", 14),
    bg="#4CAF50",
    fg="white",
    relief="flat"
)
button.pack(pady=20)

root.mainloop()
```

